package httpapi

import (
	"io"
	"net/http"
	"strings"
	"testing"

	"github.com/google/uuid"
)

// contextNoticeFragment is the middle of the sentence truncateRunes appends
// when it shortens a value for an AI prompt. The tests below never want to see
// it, and matching a fragment rather than the whole sentence keeps them honest
// if the wording is ever reworded for the model's benefit.
const contextNoticeFragment = "문서 컨텍스트가 길어"

// A stored name is data, not a prompt. These walk the routes that write one —
// the attachment upload and the document import — with a value past the 240
// rune ceiling those routes impose, and read back what the database actually
// holds. The ceiling itself is not in question; what it leaves behind is.
//
// The upload route is the plainest of them: a multipart part carries whatever
// file name the browser had, and nothing between the form and the INSERT looks
// at its length, so this is the shortest path from a person's file name to an
// attachments row.
func TestALongAttachmentFilenameIsStoredWithoutAContextNotice(t *testing.T) {
	srv := newServerUnderTest(t)
	document := markdownDocumentOwnedByAdmin(t, srv, "첨부 이름 길이 확인")

	// Four names around the ceiling. Only the first is over it; the other
	// three are there to pin down that shortening the long one does not start
	// rewriting the ordinary ones, which is the way a cut like this usually
	// goes wrong.
	for _, testCase := range []struct {
		name   string
		upload string
		want   string
	}{
		{"241 runes is cut to the first 240", strings.Repeat("긴", 241), strings.Repeat("긴", 240)},
		{"exactly 240 runes is untouched", strings.Repeat("가", 240), strings.Repeat("가", 240)},
		{"240 runes ending in an extension is untouched", strings.Repeat("가", 236) + ".txt", strings.Repeat("가", 236) + ".txt"},
		{"an ordinary name is untouched", "회의록.txt", "회의록.txt"},
		{"a single rune is untouched", "가", "가"},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			attachment := uploadAttachment(t, srv, document, testCase.upload, []byte("내용"))

			var stored string
			if err := srv.db.QueryRow(t.Context(), `SELECT name FROM attachments WHERE id=$1`, attachment).Scan(&stored); err != nil {
				t.Fatal(err)
			}
			if stored != testCase.want {
				t.Errorf("stored attachment name = %q, want %q", stored, testCase.want)
			}
			if strings.Contains(stored, contextNoticeFragment) {
				t.Errorf("the stored name carries the AI context notice: %q", stored)
			}
			if strings.ContainsAny(stored, "\r\n") {
				t.Errorf("the stored name carries a line break: %q", stored)
			}

			// The name does not stay in the database. It goes out again in the
			// download's Content-Disposition, so the round trip is read with
			// the production parser — the same mime.ParseMediaType another
			// muni uses on a handoff — and has to give back what was stored.
			resp, err := srv.admin.Get(srv.URL + "/api/v1/attachments/" + attachment.String())
			if err != nil {
				t.Fatal(err)
			}
			defer resp.Body.Close()
			body, _ := io.ReadAll(resp.Body)
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("download = %d %s", resp.StatusCode, body)
			}
			disposition := resp.Header.Get("Content-Disposition")
			if got := filenameFrom(t, disposition); got != stored {
				t.Errorf("filename read back = %q, want the stored name %q (from %q)", got, stored, disposition)
			}
		})
	}
}

// The document title takes the same ceiling by the same helper, and it is the
// more visible of the two: the title is what the document list shows, what the
// search index is built over, and what the workspace archive writes into its
// 목록.md. This drives the import route the way the import dialog does, with
// the title typed into the form rather than read out of the file.
func TestALongImportedTitleIsStoredWithoutAContextNotice(t *testing.T) {
	srv := newServerUnderTest(t)
	title := strings.Repeat("제", 241)
	want := strings.Repeat("제", 240)

	imported := importFile(t, srv, adminWorkspace(t, srv), "보고서.md", title, []byte("# 본문 제목\n\n내용입니다.\n"))
	documentID := uuid.MustParse(imported["id"].(string))

	var stored string
	if err := srv.db.QueryRow(t.Context(), `SELECT title FROM documents WHERE id=$1`, documentID).Scan(&stored); err != nil {
		t.Fatal(err)
	}
	if stored != want {
		t.Errorf("stored title = %q, want %q", stored, want)
	}
	if strings.Contains(stored, contextNoticeFragment) {
		t.Errorf("the stored title carries the AI context notice: %q", stored)
	}
	if strings.ContainsAny(stored, "\r\n") {
		t.Errorf("the stored title carries a line break: %q", stored)
	}
}

// A title at or under the ceiling is not a cut at all, and has to come back
// from the import byte for byte — including the case the ceiling is measured
// in, where 240 runes of Korean are 720 bytes.
func TestAnImportedTitleWithinTheCeilingIsStoredUnchanged(t *testing.T) {
	srv := newServerUnderTest(t)
	workspace := adminWorkspace(t, srv)

	for _, testCase := range []struct {
		name  string
		title string
	}{
		{"exactly 240 runes", strings.Repeat("제", 240)},
		{"a single rune", "제"},
		{"an ordinary title with an extension in it", "2026년 계획 v2.final"},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			imported := importFile(t, srv, workspace, "보고서.md", testCase.title, []byte("내용입니다.\n"))
			documentID := uuid.MustParse(imported["id"].(string))

			var stored string
			if err := srv.db.QueryRow(t.Context(), `SELECT title FROM documents WHERE id=$1`, documentID).Scan(&stored); err != nil {
				t.Fatal(err)
			}
			if stored != testCase.title {
				t.Errorf("stored title = %q, want it unchanged at %q", stored, testCase.title)
			}
		})
	}
}
package httpapi

import (
	"bytes"
	"context"
	"crypto/rand"
	"encoding/json"
	"io"
	"log/slog"
	"mime/multipart"
	"net/http"
	"net/http/cookiejar"
	"net/http/httptest"
	"os"
	"strings"
	"testing"

	"github.com/hkjang/muni/internal/cryptoutil"
	"github.com/hkjang/muni/internal/database"
	"github.com/jackc/pgx/v5/pgxpool"
)

// These run against a real PostgreSQL, because what they are checking is a
// transaction across four tables and a constraint the schema enforces — a fake
// would only confirm that the fake agrees with itself. CI starts a container
// and sets MUNI_TEST_DSN; locally:
//
//	docker run -d --name muni-test -e POSTGRES_PASSWORD=muni -e POSTGRES_DB=muni -p 5433:5432 postgres:16-alpine
//	MUNI_TEST_DSN="postgres://postgres:muni@127.0.0.1:5433/muni?sslmode=disable" go test ./internal/httpapi/
//
// Without it they skip.
// serverUnderTest is a muni talking to a real database, with an administrator
// already signed in — what every test here needs before it can start.
type serverUnderTest struct {
	*httptest.Server
	db    *pgxpool.Pool
	admin *http.Client
	// api is the same Server the handlers run on, so a test can call the
	// enforcement code directly and compare it with what an endpoint reports.
	api *Server
}

func newServerUnderTest(t *testing.T) *serverUnderTest {
	t.Helper()
	srv, db, api := liveServer(t)
	return &serverUnderTest{
		Server: srv,
		db:     db,
		api:    api,
		admin:  signIn(t, srv, "admin@muni.local", "provision-check-1234"),
	}
}

func liveServer(t *testing.T) (*httptest.Server, *pgxpool.Pool, *Server) {
	t.Helper()
	dsn := os.Getenv("MUNI_TEST_DSN")
	if dsn == "" {
		// Skipping is right on a laptop with no container running. In CI it
		// would mean the tests quietly stopped running the day somebody
		// removed the service, and nothing would say so.
		if os.Getenv("CI") != "" {
			t.Fatal("MUNI_TEST_DSN is unset in CI — the postgres service is gone, and these tests would have skipped silently")
		}
		t.Skip("set MUNI_TEST_DSN to run the integration tests")
	}
	ctx := context.Background()
	db, err := database.Open(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	if err := database.Migrate(ctx, db); err != nil {
		t.Fatal(err)
	}
	key := make([]byte, 32)
	_, _ = rand.Read(key)
	sealer, err := cryptoutil.NewSealer(key)
	if err != nil {
		t.Fatal(err)
	}
	// Clear only the accounts these tests make. Truncating users cascades
	// into the settings row and the instance comes back with local login off.
	// workspaces.owner_id has no ON DELETE, so the workspaces go first.
	for _, statement := range []string{
		`DELETE FROM documents WHERE owner_id IN (SELECT id FROM users WHERE email LIKE '%@example.com')`,
		`DELETE FROM documents WHERE workspace_id IN (SELECT id FROM workspaces WHERE owner_id IN (SELECT id FROM users WHERE email LIKE '%@example.com'))`,
		`DELETE FROM workspaces WHERE owner_id IN (SELECT id FROM users WHERE email LIKE '%@example.com')`,
		`DELETE FROM api_keys WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@example.com')`,
		`DELETE FROM sessions WHERE user_id IN (SELECT id FROM users WHERE email LIKE '%@example.com')`,
		`DELETE FROM users WHERE email LIKE '%@example.com'`,
	} {
		if _, err := db.Exec(ctx, statement); err != nil {
			t.Fatal(err)
		}
	}
	if err := database.Bootstrap(ctx, db, "admin@muni.local", "provision-check-1234", sealer); err != nil {
		t.Fatal(err)
	}
	api := New(db, sealer, BuildInfo{Version: "test"}, slog.New(slog.NewTextHandler(io.Discard, nil)))
	srv := httptest.NewServer(api.Handler())
	t.Cleanup(func() { srv.Close(); db.Close() })
	return srv, db, api
}

func signIn(t *testing.T, srv *httptest.Server, identity, password string) *http.Client {
	t.Helper()
	jar, _ := cookiejar.New(nil)
	client := &http.Client{Jar: jar}
	body, _ := json.Marshal(map[string]string{"identity": identity, "password": password})
	resp, err := client.Post(srv.URL+"/api/v1/auth/login", "application/json", bytes.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != 200 {
		raw, _ := io.ReadAll(resp.Body)
		t.Fatalf("login as %s = %d: %s", identity, resp.StatusCode, raw)
	}
	return client
}

func postJSON(t *testing.T, client *http.Client, url string, payload any) (int, map[string]any) {
	t.Helper()
	body, _ := json.Marshal(payload)
	resp, err := client.Post(url, "application/json", bytes.NewReader(body))
	if err != nil {
		t.Fatal(err)
	}
	defer resp.Body.Close()
	var out struct {
		Data  map[string]any `json:"data"`
		Error map[string]any `json:"error"`
	}
	raw, _ := io.ReadAll(resp.Body)
	_ = json.Unmarshal(raw, &out)
	if out.Data == nil {
		out.Data = map[string]any{}
	}
	if out.Error != nil {
		out.Data["_errorCode"] = out.Error["code"]
	}
	return resp.StatusCode, out.Data
}

func TestAnAdministratorCanCreateAnAccountThatWorks(t *testing.T) {
	srv, db, _ := liveServer(t)
	ctx := context.Background()
	admin := signIn(t, srv, "admin@muni.local", "provision-check-1234")

	status, data := postJSON(t, admin, srv.URL+"/api/v1/admin/users", map[string]any{
		"email": "minsu@example.com", "displayName": "김민수",
	})
	if status != 201 {
		t.Fatalf("create = %d %v", status, data)
	}
	temporary, _ := data["temporaryPassword"].(string)
	username, _ := data["username"].(string)
	if temporary == "" || username == "" {
		t.Fatalf("response = %v", data)
	}

	// The account is four rows, not one. Three of them make it able to work.
	var users, workspaces, members, keys int
	_ = db.QueryRow(ctx, `SELECT count(*) FROM users WHERE email='minsu@example.com'`).Scan(&users)
	_ = db.QueryRow(ctx, `SELECT count(*) FROM workspaces w JOIN users u ON u.id=w.owner_id WHERE u.email='minsu@example.com' AND w.kind='PERSONAL'`).Scan(&workspaces)
	_ = db.QueryRow(ctx, `SELECT count(*) FROM workspace_members m JOIN users u ON u.id=m.user_id WHERE u.email='minsu@example.com' AND m.role='OWNER'`).Scan(&members)
	_ = db.QueryRow(ctx, `SELECT count(*) FROM user_keys k JOIN users u ON u.id=k.user_id WHERE u.email='minsu@example.com' AND k.status='ACTIVE'`).Scan(&keys)
	if users != 1 || workspaces != 1 || members != 1 || keys != 1 {
		t.Fatalf("users=%d workspaces=%d members=%d keys=%d — an account missing any of these signs in and cannot do anything", users, workspaces, members, keys)
	}

	// The password muni chose actually signs in.
	newcomer := signIn(t, srv, "minsu@example.com", temporary)

	// And it can do exactly one thing until it is replaced.
	blocked, err := newcomer.Get(srv.URL + "/api/v1/workspaces")
	if err != nil {
		t.Fatal(err)
	}
	raw, _ := io.ReadAll(blocked.Body)
	blocked.Body.Close()
	if blocked.StatusCode != 403 || !strings.Contains(string(raw), "PASSWORD_CHANGE_REQUIRED") {
		t.Fatalf("temporary password should gate everything: %d %s", blocked.StatusCode, raw)
	}

	// /me still answers, so the browser can tell why it is stuck.
	me, err := newcomer.Get(srv.URL + "/api/v1/auth/me")
	if err != nil {
		t.Fatal(err)
	}
	meBody, _ := io.ReadAll(me.Body)
	me.Body.Close()
	if me.StatusCode != 200 || !strings.Contains(string(meBody), "mustChangePassword") {
		t.Fatalf("/me = %d %s", me.StatusCode, meBody)
	}

	status, data = postJSON(t, newcomer, srv.URL+"/api/v1/me/password", map[string]any{
		"currentPassword": temporary, "newPassword": "제가고른비밀번호입니다요",
	})
	if status != 200 {
		t.Fatalf("password change = %d %v", status, data)
	}

	// Now the account is a normal one.
	after, err := newcomer.Get(srv.URL + "/api/v1/workspaces")
	if err != nil {
		t.Fatal(err)
	}
	afterBody, _ := io.ReadAll(after.Body)
	after.Body.Close()
	if after.StatusCode != 200 {
		t.Fatalf("after the change the account must work: %d %s", after.StatusCode, afterBody)
	}
	// Its personal workspace is there and readable.
	if !strings.Contains(string(afterBody), "PERSONAL") {
		t.Fatalf("no personal workspace in %s", afterBody)
	}
}

func TestTheSameEmailIsRefusedRatherThanDuplicated(t *testing.T) {
	srv, _, _ := liveServer(t)

	// An imported document has never been through the editor, so stamp the
	// block identities that comments, citations and diffs anchor to.
	content, err = withBlockIDs(content)
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
		return
	}
	if !validDocumentJSON(content) {
		writeError(w, 400, "IMPORT_TOO_LARGE", "가져온 문서가 너무 큽니다. 파일을 나눠서 가져와 주세요.")
		return
	}
	title := strings.TrimSpace(r.FormValue("title"))
	if title == "" {
		title = strings.TrimSpace(embeddedTitle)
	}
	if title == "" {
		title = strings.TrimSuffix(filepath.Base(header.Filename), filepath.Ext(header.Filename))
	}
	if title == "" {
		title = "가져온 문서"
	}
	// The ceiling is cut with cutFilenameRunes rather than truncateRunes, and
	// the difference is the whole point. truncateRunes exists for an AI prompt:
	// when it shortens a value it says so, appending a newline and a sentence
	// telling the model the context was trimmed. A title is not a prompt — it
	// is a row in documents, and this one goes on to the document list, the
	// search index built over the title, and the 목록.md inside a workspace
	// archive. A title over 240 runes was stored with that sentence attached
	// and every one of those places showed it. cutFilenameRunes shortens and
	// says nothing, which is what stored data needs; the 240 itself is
	// unchanged.
	title = cutFilenameRunes(title, 240)
	// A Markdown file muni exported carries its title as the first heading;
	// now that the title is decided, that echo leaves the body — before the
	// search text is taken from it, so the title is not indexed twice.
	if parsed.markdown {
		content, err = dropLeadingTitle(content, title)
		if err != nil {
			writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
			return
		}
	}
	text := extractDocumentText(content)
	visibility := "RESTRICTED"
	if workspaceKind != "PERSONAL" {
		visibility = "WORKSPACE"
	}
	err = s.storeImportedDocument(r.Context(), importedDocument{
		id: documentID, workspaceID: workspaceID, folderID: folderID, ownerID: p.User.ID,
		title: title, visibility: visibility, content: content, text: text, furniture: furniture,
		reason: "import:" + strings.TrimPrefix(extension, "."), attachments: attachments,
	})
	if err != nil {
		writeError(w, 500, "IMPORT_FAILED", "가져온 문서를 저장하지 못했습니다.")
		return
	}
	s.audit(r, &p.User.ID, "IMPORT_DOCUMENT", "DOCUMENT", &documentID, map[string]any{"format": strings.TrimPrefix(extension, "."), "bytes": len(body), "images": len(attachments)})
	s.getDocumentByID(w, r, documentID)
}

// importedDocument is a document about to be created from a file: what the
// row needs, the reason its first revision records, and the pictures that
// become its attachments.
type importedDocument struct {
	id          uuid.UUID
	workspaceID uuid.UUID
	folderID    *uuid.UUID
	ownerID     uuid.UUID
	title       string
	visibility  string
	content     json.RawMessage
	text        string
	furniture   docx.Meta
	reason      string
	attachments []importedAttachment
}

// storeImportedDocument writes the document, its first revision and its
// attachments in one transaction, for the upload that makes a document and
// the handoff that takes one from another service.
func (s *Server) storeImportedDocument(ctx context.Context, doc importedDocument) error {
	return database.WithTx(ctx, s.db, func(tx pgx.Tx) error {
		if _, err := tx.Exec(ctx, `INSERT INTO documents(id,workspace_id,folder_id,owner_id,title,visibility,content_json,content_text,revision_no,page_header,page_footer,page_orientation) VALUES($1,$2,$3,$4,$5,$6,$7,$8,1,$9,$10,$11)`,
			doc.id, doc.workspaceID, doc.folderID, doc.ownerID, doc.title, doc.visibility, doc.content, doc.text,
			truncateRunes(doc.furniture.Header, 200), truncateRunes(doc.furniture.Footer, 200), orientationOf(doc.furniture.Landscape)); err != nil {
			return err
		}
		if _, err := tx.Exec(ctx, `INSERT INTO document_revisions(document_id,revision_no,content_json,content_text,author_id,reason) VALUES($1,1,$2,$3,$4,$5)`, doc.id, doc.content, doc.text, doc.ownerID, doc.reason); err != nil {
			return err
		}
		for _, attachment := range doc.attachments {
			sum := sha256.Sum256(attachment.Data)
			// Same cut as the title above, and for a sharper reason: this name
			// leaves again in the download's Content-Disposition, so a prompt's
			// "context was shortened" sentence would end up in the file a
			// person saves. All three places that write attachments.name use
			// cutFilenameRunes, so the same picture keeps the same name however
			// it arrived.
			if _, err := tx.Exec(ctx, `INSERT INTO attachments(id,document_id,uploader_id,name,media_type,size_bytes,sha256,data) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
				attachment.ID, doc.id, doc.ownerID, cutFilenameRunes(attachment.Name, 240), attachment.MediaType, len(attachment.Data), hex.EncodeToString(sum[:]), attachment.Data); err != nil {
				return err
			}
		}
		return nil
	})
}

// upload is what a document file turns into: the content, the pictures it
// carried, the title it held in itself and what it said about the paper.
type upload struct {
	content   json.RawMessage
	maxBytes := int64(all.Security.MaxUploadMB) << 20
	r.Body = http.MaxBytesReader(w, r.Body, maxBytes+(1<<20))
	if err := r.ParseMultipartForm(maxBytes); err != nil {
		writeError(w, 413, "FILE_TOO_LARGE", fmt.Sprintf("파일은 %dMB 이하여야 합니다.", all.Security.MaxUploadMB))
		return
	}
	file, header, err := r.FormFile("file")
	if err != nil {
		writeError(w, 400, "FILE_REQUIRED", "가져올 파일이 필요합니다.")
		return
	}
	defer file.Close()
	body, err := io.ReadAll(io.LimitReader(file, maxBytes+1))
	if err != nil || int64(len(body)) > maxBytes {
		writeError(w, 413, "FILE_TOO_LARGE", "파일 크기 제한을 초과했습니다.")
		return
	}
	extension := strings.ToLower(filepath.Ext(header.Filename))
	if extension == "" {
		extension = extensionFromMediaType(header.Header.Get("Content-Type"), body)
	}
	parsed, err := parseUpload(r.Context(), extension, body)
	if errors.Is(err, errUnsupportedUpload) {
		writeError(w, 400, "UNSUPPORTED_IMPORT", err.Error())
		return
	}
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "파일 내용을 읽지 못했습니다: "+err.Error())
		return
	}
	attachments, content, err := prepareImportedAssets(parsed.assets, parsed.content)
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
		return
	}
	content, err = withBlockIDs(content)
	if err != nil {
		writeError(w, 400, "IMPORT_PARSE_FAILED", "가져온 문서를 변환하지 못했습니다: "+err.Error())
		return
	}
	if !validDocumentJSON(content) {
		writeError(w, 400, "IMPORT_TOO_LARGE", "가져온 문서가 너무 큽니다. 파일을 나눠서 가져와 주세요.")
		return
	}
	err = database.WithTx(r.Context(), s.db, func(tx pgx.Tx) error {
		for _, attachment := range attachments {
			sum := sha256.Sum256(attachment.Data)
			if _, err := tx.Exec(r.Context(), `INSERT INTO attachments(id,document_id,uploader_id,name,media_type,size_bytes,sha256,data) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,
				attachment.ID, documentID, p.User.ID, cutFilenameRunes(attachment.Name, 240), attachment.MediaType, len(attachment.Data), hex.EncodeToString(sum[:]), attachment.Data); err != nil {
				return err
			}
		}
		return nil
	})
	if err != nil {
		writeError(w, 500, "IMPORT_FAILED", "가져온 그림을 저장하지 못했습니다.")
		return
	}
	title := strings.TrimSpace(parsed.title)
	if title == "" {
		title = strings.TrimSuffix(filepath.Base(header.Filename), filepath.Ext(header.Filename))
	}
	s.audit(r, &p.User.ID, "IMPORT_INTO_DOCUMENT", "DOCUMENT", &documentID, map[string]any{"format": strings.TrimPrefix(extension, "."), "bytes": len(body), "images": len(attachments)})
	writeData(w, 200, map[string]any{
		"content": content,
		// This title is not a log line: the editor reads it out of this
		// response and puts it in the title box, so it becomes a documents row
		// as surely as the one importDocument writes. Cutting it the same way
		// keeps the two import paths agreed — importing the same over-long
		// title into a new document and into an open one now gives the same
		// title, where before only one of them carried the prompt's notice.
		"title":     cutFilenameRunes(title, 240),
		"header":    truncateRunes(parsed.furniture.Header, 200),
		"footer":    truncateRunes(parsed.furniture.Footer, 200),
		"landscape": parsed.furniture.Landscape,
		"format":    strings.TrimPrefix(extension, "."),
		"images":    len(attachments),
	})
}

// docxImport converts a Word file, keeping headings, lists, tables, inline
// formatting and embedded images.
func docxImport(body []byte) (json.RawMessage, []richdoc.Asset, docx.Meta, error) {
	document, assets, meta, err := docx.Parse(body)
